class Solution {
    private int n;
    private int target;
    private int[] nums;
    private int fullMask;
    private int[] sumMask;
    private int[] memo; // -1 unknown, 0 false, 1 true

    public boolean canPartitionKSubsets(int[] nums, int k) {
        this.n = nums.length;
        this.nums = nums;
        int total = 0;
        for (int v : nums) total += v;
        if (total % k != 0) return false;
        this.target = total / k;
        for (int v : nums) if (v > target) return false;
        // Precompute sum for every mask
        fullMask = (1 << n) - 1;
        sumMask = new int[1 << n];
        for (int mask = 1; mask <= fullMask; mask++) {
            int lsb = mask & -mask;
            int idx = Integer.numberOfTrailingZeros(lsb);
            sumMask[mask] = sumMask[mask ^ lsb] + nums[idx];
        }
        memo = new int[1 << n];
        for (int i = 0; i < memo.length; i++) memo[i] = -1;
        return dfs(0);
    }

    private boolean dfs(int mask) {
        if (mask == fullMask) return true;
        if (memo[mask] != -1) return memo[mask] == 1;
        int cur = sumMask[mask] % target;
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) == 0) {
                if (cur + nums[i] <= target) {
                    if (dfs(mask | (1 << i))) {
                        memo[mask] = 1;
                        return true;
                    }
                }
            }
        }
        memo[mask] = 0;
        return false;
    }
}

